// 正式作者军营任职与四课生成唯一见闻；只走World命令和原检查点，不注入事实。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/checkpoint/checkpoint_envelope.hpp"
#include "resident/storage/common_codec.hpp"
#include <algorithm>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;using namespace boundary;namespace fs=std::filesystem;
Integer checks=0;V::Array trace;
const StableId actor="qingxi::actor.player",office="qingxi::office.north_leader",unit="qingxi::unit.north.work_detail",card_id="insights::card.vi04";
// 失败保原始错误码和完整命令轨迹，不用手工状态修补前置。
void check(bool value,const StableId& message){++checks;if(!value)throw std::runtime_error(message);}
template<class T>T take(Outcome<T> value,const StableId& label){if(!value.ok)throw std::runtime_error(label+":"+value.error.original.code+":"+value.error.original.path);return std::move(value.value);}
void take(Status value,const StableId& label){if(!value.ok)throw std::runtime_error(label+":"+value.error.original.code+":"+value.error.original.path);}
StableId read(const fs::path& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("missing:"+p.string());std::ostringstream s;s<<f.rdbuf();return s.str();}
StableId json(const V& v){return take(render_boundary_json(v),"render");}
V parse(const fs::path& p){return take(parse_boundary_json(read(p)),"parse");}
void write(const fs::path& p,const StableId& bytes){check(!fs::exists(p),"keep prior evidence");std::ofstream f(p,std::ios::binary);f.write(bytes.data(),static_cast<std::streamsize>(bytes.size()));check(bool(f),"write original");}
void write(const fs::path& p,const V& v){write(p,json(v)+"\n");}
bool ok(const V& v){const auto* x=v.find("ok");return x&&x->as<bool>()&&*x->as<bool>();}
Outcome<LiveOperationResult> raw_query(ResidentReplaySession& w,const StableId& name,const V& args=V{V::Dict{}}){LiveOperation c;c.source=take(w.identity(),"identity");c.payload=obj({{"query_id",V{name}},{"args",args}});return w.execute_live(c);}
V query(ResidentReplaySession& w,const StableId& name,const V& args=V{V::Dict{}}){return take(raw_query(w,name,args),name).result;}
V command(ResidentReplaySession& w,const StableId& kind,const V& params=V{V::Dict{}},bool preview=false){auto ctx=query(w,"command_context");LiveOperation c;c.kind=preview?LiveOperationKind::preview:LiveOperationKind::command;c.source=take(w.identity(),"command identity");c.payload=obj({{"kind",V{kind}},{"params",params},{"actor_id",field(ctx,"actor_id","context")}});if(!preview){c.payload.as<V::Dict>()->emplace_back("request_seq",field(ctx,"next_request_seq","context"));c.payload.as<V::Dict>()->emplace_back("expected_revision",field(ctx,"revision","context"));}auto r=take(w.execute_live(c),kind).result;trace.push_back(obj({{"preview",V{preview}},{"command",c.payload},{"result",r}}));if(!ok(r))throw std::runtime_error(kind+":"+json(r));return r;}
void finish(ResidentReplaySession& w){for(int n=0;n<16;++n){if(get_string(query(w,"action_context"),"action_id","action").empty())return;command(w,"advance");}throw std::runtime_error("bounded action did not finish");}
// 一页只有作者所选VI04；外部发现只供显示，不是本人经历来源。
V card(ResidentReplaySession& w,bool discovered=false){auto page=query(w,"insight_cards",obj({{"discovered",V{discovered?V::Array{V{card_id}}:V::Array{}}},{"limit",V{Integer{1}}}}));const auto& rows=array(field(page,"cards","page"),"cards");check(rows.size()==1&&get_string(rows[0],"card_id","card")==card_id,"exact authored insight");return rows[0];}
void empty(const V& row){check(!get_bool(row,"acquired_this_world","card")&&!get_bool(row,"experienced_this_world","card")&&field(row,"experience","card").as<std::monostate>(),"no completed training means no current experience");}
void saved(ResidentReplaySession& w,const fs::path& out,const StableId& name){write(out/(name+".json"),json(take(w.export_state(),"state")));auto bytes=take(w.checkpoint(),"bank");write(out/(name+".hmcb"),StableId(bytes.begin(),bytes.end()));}
void exact(ResidentReplaySession& w,const fs::path& out,const StableId& name){check(json(take(w.export_state(),"cold state"))==read(out/(name+".json")),"full cold world exact");auto bytes=take(w.checkpoint(),"cold bank");check(StableId(bytes.begin(),bytes.end())==read(out/(name+".hmcb")),"full bank re-encode exact");}
// 本作者沿原清溪人口/围城组合；见闻目录能力不新建任何checkpoint段或版本。
std::vector<CheckpointDomain> domains(){return {{"common",6},{"travel",3},{"military",4},{"interaction",2},{"social",1},{"estate",2},{"tasks",1},{"family",1},{"personal",1},{"growth",3},{"local_economy",2},{"organization",2},{"affairs",1},{"director",1},{"dynamic_tasks",2},{"dynamic_social",1},{"population_military",2},{"siege_integration",1},{"military_integration",1}};}
void markers(ResidentReplaySession& w,const V& catalog){auto bank=take(w.checkpoint(),"marker bank");auto original=take(w.export_state(),"original");auto env=take(inspect_checkpoint(bank,domains()),"original military domain layout");for(const StableId variation:{"missing","duplicate","wrong"}){auto bad=env;auto& versions=bad.identity.catalog.module_versions;auto it=std::find_if(versions.begin(),versions.end(),[](const auto& x){return x.first=="growth_insights";});check(it!=versions.end(),"explicit insight module");if(variation=="missing")versions.erase(it);else if(variation=="duplicate")versions.push_back(*it);else it->second="2";auto bytes=take(encode_checkpoint(bad),"alter module only");auto cold=create_resident_replay_session();if(variation!="missing")check(!cold->inspect_checkpoint_selection(bytes).ok,"title rejects wrong or duplicate module");check(!cold->initialize_checkpoint(catalog,bytes).ok&&!cold->identity().ok,"full selected catalog rejects changed insight identity");check(!w.restore(bytes).ok&&compare_boundary(original,take(w.export_state(),"unchanged world")).exact()&&take(w.checkpoint(),"unchanged bank")==bank,"rejected restore leaves all world bytes unchanged");}}
}

// 三个真实进程分别产生中途、完成后和最终冷恢复原件；新局仅从正式目录创建。
int main(int argc,char** argv){fs::path evidence,run;try{
    if(argc!=5)throw std::runtime_error("usage: growth_insight_world_test produce|consume|verify CATALOG REQUEST EVIDENCE");const StableId mode=argv[1];evidence=argv[4];run=evidence/mode;check(!fs::exists(run),"fresh evidence mode");fs::create_directories(run);const auto catalog=parse(argv[2]),request=parse(argv[3]);check(ok(catalog)&&catalog.find("pack_set_digest"),"actual Installed PreparedCatalog required");check(get_string(request,"scenario_id","request")=="insights::scenario.camp_training","actual authored camp scenario");auto w=create_resident_replay_session();
    if(mode=="produce"){
        take(w->initialize_native(catalog,request),"formal new world");check(get_string(query(*w,"command_context"),"actor_id","context")==actor,"original named actor selected");empty(card(*w));auto before=take(w->export_state(),"before discovery query");auto known=card(*w,true);empty(known);check(get_bool(known,"discovered","card")&&compare_boundary(before,take(w->export_state(),"after discovery query")).exact(),"external discovery reveals text without changing world");check(!raw_query(*w,"insight_cards",obj({{"actor_id",V{"qingxi::actor.north_officer"}}})).ok,"cannot read another actor experience");
        command(*w,"move_local",obj({{"place_id",V{"qingxi::place.north.camp"}}}));finish(*w);auto contact=query(*w,"military_camp_provider_context");check(get_string(contact,"provider_actor_id","contact")=="qingxi::actor.north_officer","real current military provider");command(*w,"office_accept",obj({{"office_id",V{office}},{"context",contact}}));finish(*w);empty(card(*w));saved(*w,evidence,"appointed");
        auto params=obj({{"office_id",V{office}},{"unit_id",V{unit}}});auto quote=command(*w,"military_train",params,true);write(run/"actual-training-quote.json",quote);command(*w,"military_train",params);const auto action=get_string(query(*w,"action_context"),"action_id","action");check(!action.empty(),"actual original military training started");command(*w,"advance");command(*w,"advance");check(get_string(query(*w,"action_context"),"action_id","action")==action,"two lessons remain same action");empty(card(*w));saved(*w,evidence,"midpoint");write(evidence/"course.json",obj({{"action_id",V{action}}}));markers(*w,catalog);
    }else{
        check(mode=="consume"||mode=="verify","known cold mode");const StableId name=mode=="consume"?"midpoint":"completed";auto raw=read(evidence/(name+".hmcb"));Bytes bytes(raw.begin(),raw.end());take(w->inspect_checkpoint_selection(bytes),"title inspect");check(!w->identity().ok,"title does not instantiate world");take(w->initialize_checkpoint(catalog,bytes),"full new-process cold initialize");exact(*w,evidence,name);
        if(mode=="consume"){empty(card(*w));command(*w,"advance");empty(card(*w));command(*w,"advance");check(get_string(query(*w,"action_context"),"action_id","action").empty(),"fourth real lesson completes original action");}
        const auto row=card(*w);check(get_bool(row,"acquired_this_world","card")&&get_bool(row,"experienced_this_world","card"),"current actor acquired real military experience");const auto& source=field(row,"experience","card");check(get_string(source,"actor_id","source")==actor&&get_string(source,"fact_id","source")==get_string(parse(evidence/"course.json"),"action_id","course")&&get_string(source,"garrison_id","source")=="qingxi::garrison.north"&&get_string(source,"unit_id","source")==unit,"experience binds original participant action and camp");check(get_int(source,"completed_tick","source")-get_int(source,"started_tick","source")==4&&!row.find("learned")&&!source.find("office_id")&&!source.find("execution_epoch"),"four actual lessons; no borrowed office skill or transient epoch");auto before=take(w->export_state(),"before repeated observation");card(*w);check(compare_boundary(before,take(w->export_state(),"after observation")).exact(),"reading experience grants no reward");
        if(mode=="consume"){saved(*w,evidence,"completed");write(evidence/"completed-card.json",row);}else{check(compare_boundary(row,parse(evidence/"completed-card.json")).exact(),"permanent experience exact across cold epoch");auto fresh=create_resident_replay_session();take(fresh->initialize_native(catalog,request),"another actual new life");auto initial=take(fresh->export_state(),"new life before discovery");auto discovered=card(*fresh,true);empty(discovered);check(get_bool(discovered,"discovered","card")&&compare_boundary(initial,take(fresh->export_state(),"new life after discovery")).exact(),"prior discovery does not transfer training or appointment");write(run/"fresh-world-card.json",discovered);}
    }
    write(run/"commands.json",V{trace});write(run/"result.json",obj({{"ok",V{true}},{"mode",V{mode}},{"checks",V{checks}}}));std::cout<<"GROWTH_INSIGHT_WORLD "<<mode<<" "<<checks<<" checks 0 failures\n";return 0;
}catch(const boundary::DecodeFailure& error){const auto message=error.error.original.code+":"+error.error.original.path;if(!run.empty()&&fs::exists(run)){write(run/"commands.json",V{trace});write(run/"failure.json",obj({{"ok",V{false}},{"message",V{message}},{"checks",V{checks}}}));}std::cerr<<"GROWTH_INSIGHT_WORLD boundary failure "<<message<<'\n';return 1;
}catch(const std::exception& error){if(!run.empty()&&fs::exists(run)){if(!fs::exists(run/"commands.json"))write(run/"commands.json",V{trace});if(!fs::exists(run/"failure.json"))write(run/"failure.json",obj({{"ok",V{false}},{"message",V{StableId{error.what()}}},{"checks",V{checks}}}));}std::cerr<<"GROWTH_INSIGHT_WORLD "<<checks<<" checks 1 failure: "<<error.what()<<'\n';return 1;}}
